// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {

        bool ok;
        uint64 _number = 1;
        uint64 _timestamp = 2;
        uint256 _basefee = 3;
        bytes32 _hash = bytes32(uint256(4));
        uint64 _sequenceNumber = 5;
        bytes32 _batcherHash = bytes32(uint256(6));
        uint256 _l1FeeOverhead = 7;
        uint256 _l1FeeScalar = 8;

        vm.prank(caller);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        bytes memory payload = abi.encodeWithSelector(
            L1Block.setL1BlockValues.selector,
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        vm.prank(caller);
        (bool succ, bytes memory data) = address(c).call(payload);

        address depositor = c.depositorAccount();
        if (caller != depositor) {
            bytes memory expectedPrefix = abi.encodeWithSelector(
                bytes4(keccak256("Error(string)")),
                string(abi.encodePacked("L1Block: only the depositor account can set L1 block values"))
            );
            assertTrue(!succ && keccak256(data) == keccak256(expectedPrefix));
        } else {
            assertTrue(succ);
        }
    }
}
